const e={title:"TripReel - Gratis Reseanimationsapp: Förvandla Bilder till Vackra Videor",description:"Skapa fantastiska resevideor med animerade kartor och flygrutter. Gratis reseanimationsapp med 3D-glob rutkartläggning. Förvandla dina bilder till vackra resevideor automatiskt. Integritet först, fungerar offline.",keywords:"reseanimationsapp, rese-kart-animationsapp, rese-rutt-animationsapp, flyg-animationsapp, resevideomakare, automatisk resevideo, animerad rese-karta, flygrutt-animation, reseanimation, glob-animation, rese-sammanfattningsvideo, bild till video, rese-höjdpunkter, gratis reseapp, offline videomakare, integritet reseapp, kamerarulle video"},a={logoAlt:"TripReel-logotyp",appName:"TripReel",howItWorks:"Så fungerar det",video:"Video",features:"Funktioner",theApp:"Appen"},t={badge:"Förvandla foton till reseberättelser",title1:"Ditt fotobibliotek,",title2:"Fullt utnyttjat",description:"TripReel skapar automatiskt vackra resevideor från dina fotons platser. Se dina resor vakna till liv med fantastiska animerade ruttkartor och flygrutter på ett 3D-klot, medan dina data förblir privata och säkra.",secure:"100% säkert",worksOffline:"Fungerar offline",globeAlt:"TripReel globanimation"},r={title:"Så fungerar det",subtitle:"Tre enkla steg för att skapa din perfekta resevideo",step1:{title:"Tillåt fotoåtkomst",description:"Ge TripReel åtkomst till ditt fotobibliotek. Appen läser endast platsmetadata, inget annat."},step2:{title:"Automatisk reseidentifiering",description:"TripReel analyserar platsmetadata och hittar intelligent dina resor baserat på datum och platser."},step3:{title:"Generera din video",description:"Se din resa veckla ut sig på en vacker globanimation, redo att dela på sociala medier."}},i={title:"Se magin ske",subtitle:"Se hur TripReel förvandlar ditt fotobibliotek till fantastiska resevideor",caption:"Så här kommer din slutgiltiga resevideo att se ut"},n={title:"Allt du behöver",subtitle:"Kraftfulla funktioner designade för moderna resenärer",twoTap:{title:"Resevideor med två tryck",description:"Skapa fantastiska resevideor från ditt fotobibliotek med bara två tryck. Ingen redigering behövs."},smartTrip:{title:"Smart reseidentifiering",description:"Hittar och grupperar automatiskt dina resor genom att analysera datum och platsmetadata från dina foton."},globe:{title:"Vacker globanimation",description:"Se din resa vakna till liv med ett fantastiskt 3D-klot som visar dina animerade reserutter och flygrutter över hela världen."},privacy:{title:"Integritet först",description:"Allt bearbetas på din enhet. Dina foton lämnar aldrig din telefon. Fungerar i flygplansläge."},customStyles:{title:"Anpassade stilar",description:"Välj bland flera jordstilar och anpassningar för att matcha din estetik och göra varje video unik."},manualControl:{title:"Manuell kontroll",description:"Du kan manuellt lägga till helt nya resor om platstjänster inte var aktiverade på din enhet."}},s={title:"Kreativa videoidéer",subtitle:"Bli inspirerad av vad du kan skapa med TripReel. Från snabba helgresor till helårsäventyr, skapa fantastiska resevideor för varje resa.",description:"Oavsett om du skapar en resekartanimation, dokumenterar en flygrutt eller gör en årssammanfattning, gör TripReel det enkelt att förvandla dina minnen till delbara videor.",ideas:{yearRecap:{title:"2025 resesammanfattning",description:"Skapa din årliga resesammanfattning för 2025 automatiskt"},europeRoadTrip:{title:"Europa bilresa",description:"Visa ditt europeiska äventyr med animerade ruttkartor"},southeastAsia:{title:"Sydostasien-resa",description:"Visualisera din backpacking-rutt genom flera länder"},japanRail:{title:"Japan tågresa",description:"Skapa kartvideor av dina tågrutter genom Japan"},crossCountry:{title:"Tvärs över USA",description:"Förvandla din amerikanska bilresa till en episk ruttvideo"},islandHopping:{title:"Öhopp",description:"Visa dina resor från ö till ö med fantastiska 3D-animationer"},worldTour:{title:"Världsturné-montage",description:"Flera resor i en fantastisk global resevideo"},travelPlans:{title:"Reseplaner 2026",description:"Visualisera och planera dina spännande reseäventyr för 2026"},lifetimeTravel:{title:"Livslång reseberättelse",description:"Skapa en video som visar alla dina resor genom livet"},regionalExplorer:{title:"Regional upptäckare",description:"Kartlägg dina äventyr genom stater, provinser och regioner"},festivalCircuit:{title:"Festivalkretsen",description:"Kartlägg din musikfestival- och eventresa"},bikeRoutes:{title:"Mina stadsresor",description:"Visa alla dina stadsflykter"}}},l={title:"Appen",subtitle:"Tillgänglig nu i App Store",alt1:"Automatiska resevideor - Skapa fantastiska videor på sekunder",alt2:"Fotoplatsidentifiering - Använder dina fotons metadata",alt3:"Reseidentifiering - Grupperar dina resor automatiskt",alt4:"Vackra jordvideor - Globanimation av din resa",alt5:"Anpassade stilar - Personalisera dina resevideor"},o={comingSoon:"Kommer snart",androidTitle:"Android-appen kommer snart!",androidMessage:'Android-versionen är inte tillgänglig ännu men kommer snart. Skicka ett meddelande till mig på <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> så meddelar jag dig när den är klar!',gotIt:"Uppfattat!"},d={title:"Vanliga frågor",subtitle:"Allt du behöver veta om TripReel",q1:{question:"Kan jag verkligen använda appen fullt ut i flygplansläge?",answer:"Ja! För premiumanvändare kan appen användas helt offline i flygplansläge utan begränsningar. För icke-premiumanvändare är vissa funktioner annonsfinansierade som kan kräva tillfällig aktivering av internet, men för premiumanvändare finns det inga annonser och appen kan användas fullt ut i flygplansläge."},q2:{question:"Jag har uppgraderat till Premium, hur tar jag bort vattenstämpeln?",answer:"Många frågar vilken app som användes för att skapa dessa videor, så efter uppgradering till premium har du möjlighet att lägga till en mindre version av vattenstämpeln (endast med appnamnet) eller ta bort den helt om du vill."},q3:{question:"Är mina fotodata säkra och privata?",answer:"Absolut! TripReel läser endast platsmetadata från dina foton - vi får aldrig åtkomst till, lagrar eller överför det faktiska fotoinnehållet. All bearbetning sker lokalt på din enhet, och ingen data lämnar någonsin din telefon. Du kan verifiera detta genom att använda appen i flygplansläge - den fungerar perfekt offline!"},q4:{question:"Vad händer om mina foton inte har platsdata?",answer:"Inga problem! Om platstjänster inte var aktiverade när du tog dina foton kan du manuellt skapa resor och lägga till platser själv. Appen ger dig full kontroll för att anpassa din resetidslinje."},q5:{question:"Hur identifierar appen mina resor automatiskt?",answer:"TripReel analyserar platsmetadata och tidsstämplar från dina foton för att intelligent identifiera när och var du har rest. Den grupperar närliggande platser och datum tillsammans för att automatiskt identifiera dina resor utan manuellt arbete."},q6:{question:"Kan jag anpassa utseendet på mina videor?",answer:"Ja! Du kan välja bland flera jordstilar och anpassa olika aspekter av dina animerade resevideor för att matcha din personliga estetik. Premiumanvändare får tillgång till ytterligare ruttanimationsstilar, kartteman och flygruttsalternativ."},q7:{question:"Måste jag skapa ett konto?",answer:"Inget konto krävs! TripReel fungerar omedelbart efter nedladdning. Det finns ingen registrering, ingen inloggning och ingen personlig information behövs. Ladda bara ner appen och börja skapa dina resevideor direkt."},q8:{question:"Varför saknas en plats från min resa?",answer:"Appen kan endast fungera med tillgänglig data, så först och främst behöver du minst några foton på den platsen. För det andra måste du se till att du hade platsdata aktiverat när du var där. För det tredje kan ibland dålig GPS-mottagning orsaka fel platsdata. Om du har uteslutit allt detta och din plats fortfarande inte visas kan du manuellt lägga till den platsen från Trips Overview > Edit-knappen. Använd också Contact för att rapportera problemet."},q9:{question:"Var kan jag dela min fantastiska video?",answer:"Självklart kan du också dela den på alla sociala plattformar. För att bättre passa plattformen tillåter appen olika bildförhållanden för dina videor."},q10:{question:"Var kan jag rapportera en bugg?",answer:"Kontakta mig bara direkt på marian@qod.ee och förklara kort vad problemet är."}},p={title:"E-postsupport",description:"Om du har någon feedback eller stöter på problem, tveka inte att kontakta mig direkt på denna e-post så kommer jag personligen att läsa och hantera din förfrågan så snabbt som möjligt. Tack för att du använder appen!",close:"Stäng"},g={default:{title:"🍪 Kakor",message:"Vi använder kakor på TripReel-webbplatsen för att förbättra din upplevelse. Inga personuppgifter samlas in.",accept:"Acceptera",decline:"Avböj",details:"Detaljer"},theme:{title:"🍪 Kakor",message:"🌙 För att spara dina temainställningar måste du acceptera nödvändiga kakor på TripReel-webbplatsen. Utan dem kan ditt temaval inte sparas.",accept:"Acceptera",decline:"Avböj",details:"Detaljer"}},m={privacy:"Appens sekretesspolicy",cookies:"Webbplatsens kakpolicy",contact:"Kontakt",cookiePreferences:"Kakinställningar",madeWith:"Skapad med",forTravelers:"för resenärer över hela världen",copyright:"© {{year}} TripReel."},k={title:"Redo att dela din resa?",description:"Ladda ner TripReel idag och förvandla ditt fotobibliotek till vackra resevideor med animerade kartor och rutter. Dina äventyr förtjänar att firas.",features:"Gratis att ladda ner • Snabbt och bekvämt • Garanterad integritet"},f={meta:e,header:a,hero:t,howItWorks:r,videoSection:i,features:n,videoIdeas:s,screenshots:l,appStore:o,faq:d,contact:p,cookieBanner:g,footer:m,cta:k};export{o as appStore,p as contact,g as cookieBanner,k as cta,f as default,d as faq,n as features,m as footer,a as header,t as hero,r as howItWorks,e as meta,l as screenshots,s as videoIdeas,i as videoSection};
